    INSERT INTO tb_logs (table_name, table_operation, db_user, operation_description, operation_date, operation_status)
    VALUES ('tb_products',
        IF(OLD.status = 1 AND NEW.status = 0, 'Soft Delete', 'Update'),
        USER(),
        CONCAT('Producto actualizado, ID=', OLD.ID,
               ', name_anterior=', OLD.name, ' -> nuevo=', NEW.name,
               ', price_anterior=', OLD.current_price, ' -> nuevo=', NEW.current_price,
               ', stock_anterior=', OLD.current_stock, ' -> nuevo=', NEW.current_stock,
               ', status_anterior=', OLD.status, ' -> nuevo=', NEW.status),
        CURRENT_TIMESTAMP, b'1');
END */;;
