CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_soft_delete_product`(IN p_id INT)
BEGIN
    DECLARE v_sku VARCHAR(50);

    SELECT SKU INTO v_sku
    FROM tb_products
    WHERE ID = p_id AND status = 1;

    IF v_sku IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Producto no existe o ya est� inactivo';
    END IF;

    UPDATE tb_products
    SET status = 0, last_update = NOW()
    WHERE ID = p_id;
END ;;
